def _hit_rate(X, J, elim_idx):
    """Vectorized: fraction of Dirichlet draws X (K x n) reproducing the
    observed elimination (eliminated couple has strictly lowest combined C)."""
    A = ALPHA * J[None, :] + (1 - ALPHA) * X            # combined scores, K x n
    e_min = A[:, elim_idx].min(axis=1)                  # best (lowest) eliminated
    mask = np.ones(X.shape[1], dtype=bool)
    mask[elim_idx] = False
    return float(np.mean(e_min[:, None] <= A[:, mask] - 1e-12 @ np.ones((1, A[:, mask].shape[1]))
                         if False else np.all(e_min[:, None] <= A[:, mask] - 1e-12, axis=1)))

